        }

        // Ninja b attaque Ninja a
        float jet_b = (float)rand() / RAND_MAX;
        if (jet_b > a.esquive) {
            float degats_b = b.attaque - a.defense;
            if (degats_b < 0) degats_b = 0; // Ne peut pas être négatif
            a.vie -= degats_b;
