int* Tableau_des_score(int nb_joueur){
    // Vérification du nombre de joueurs minimum
    if (nb_joueur < 50){
        printf("Pas assez de joueurs");
        exit(EXIT_FAILURE);
    }
    // Allocation dynamique de mémoire pour le tableau des scores
