```c
int levenshtein(char* strA, char* strB){
    int longeurA = strlen(strA);
    int longeurB = strlen(strB);

    if (min(longeurA, longeurB) == 0)
    {
        return max(longeurA, longeurB);
    }
    if (strA[0]==strB[0])
    {
        return levenshtein(strA+1,strB+1);
    }

