    rewind(fichier); // Retourner au début du fichier

    // tableau d'étudiants
    Etudiant *tab = malloc(*nb_etu * sizeof(Etudiant));

    // Lire les étudiants depuis le fichier
    fread(tab, sizeof(Etudiant), *nb_etu, fichier);

    fclose(fichier);
    return tab;
}


