```c
typedef struct ChainonF {
    pArbre arbre;
    struct ChainonF *suivant;
} ChainonF;

typedef struct {
    ChainonF *tete;
    ChainonF *queue;
} File;

void enfiler(File *f, pArbre a) {
    ChainonF *c = malloc(sizeof(ChainonF));
    if (c == NULL) {
        fprintf(stderr, "Erreur d'allocation\n");
        exit(EXIT_FAILURE);
    }
    c->arbre = a;
    c->suivant = NULL;
    if (f->queue == NULL) {
        f->tete = c;
    } else {
        f->queue->suivant = c;
    }
    f->queue = c;
}

pArbre defiler(File *f) {             /* à appeler sur une file non vide */
    ChainonF *c = f->tete;
    pArbre a = c->arbre;
    f->tete = c->suivant;
    if (f->tete == NULL) {
        f->queue = NULL;
    }
    free(c);
    return a;
}

void parcoursLargeur(pArbre a) {
    if (a == NULL) {
        return;
    }
    File f = {NULL, NULL};
    enfiler(&f, a);
    while (f.tete != NULL) {
        pArbre n = defiler(&f);
        traiter(n);
        if (n->fg != NULL) {
            enfiler(&f, n->fg);
        }
        if (n->fd != NULL) {
            enfiler(&f, n->fd);
        }
    }
}
```

