}

int tailleArbre(pArbre a) {                /* nombre total de nœuds */
    if (a == NULL) {
        return 0;
    }
    return 1 + tailleArbre(a->fg) + tailleArbre(a->fd);
}

int nmbNoeudsInternes(pArbre a) {          /* nœuds qui ne sont pas des feuilles */
