    float g = eval(a->fg);
    float d = eval(a->fd);
    switch (a->terme.typeTerme) {
        case '+':
            return g + d;
        case '-':
            return g - d;
        case 'x':
        case '*':
            return g * d;
        case '/':
            if (d == 0) {
                fprintf(stderr, "division par zéro\n");
                exit(EXIT_FAILURE);
            }
            return g / d;
        default:
            fprintf(stderr, "opérateur inconnu\n");
            exit(EXIT_FAILURE);
    }
}

