```c
void remplirAleatoireSansDoublon(int *tab, int n) {
    pArbre deja = NULL;
    int k = 0;
    while (k < n) {
        int x = rand() % 101;
        if (!recherche(deja, x)) {
            deja = insertABR(deja, x);
            tab[k] = x;
            k++;
