#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct Crepe {
    int diametre;
    struct Crepe *suivant;
} Crepe;

typedef Crepe *Pcrepe;

Pcrepe nouvelleCrepe(Crepe c) {
    Pcrepe n = malloc(sizeof(Crepe));
    if (n == NULL) {
