```c
int prefixeRecherche(pArbre a, int e, int *nb) {
    if (a == NULL) {
        return 0;
    }
    (*nb)++;
    if (a->elmt == e) {
        return 1;
    }
    return prefixeRecherche(a->fg, e, nb) || prefixeRecherche(a->fd, e, nb);
