																#include "sqrt2.h"



																double approximer_sqrt2_theon(int n) {

																    int p = 1, q = 1;

																    for (int i = 0; i < n; i++) {

																        int p_new = p + 2*q;

																        int q_new = p + q;

																        p = p_new;

																        q = q_new;

																    }

																    return (double)p / q;

																}

