#include <mpi.h> 
#include <stdio.h> 
#include <stdlib.h> 

#define N 1000000  // Nombre total de trapèzes 
#define A 0.0 
#define B 1.0 
#define TASK_SIZE 10000  // Taille d'une tâche dynamique 
double f(double x) { 
     return x * x; 
} 
double trapezoidal_rule(double a, double b, int n) { 
 double h = (b - a) / n; 
 double sum = (f(a) + f(b)) / 2.0; 
 for (int i = 1; i < n; i++) { 
        sum += f(a + i * h); 
 } 
 return sum * h; 
} 

int main(int argc, char** argv)  
{ 
 int rank, size; 
 MPI_Init(&argc, &argv); 
 MPI_Comm_rank(MPI_COMM_WORLD, &rank); 
 MPI_Comm_size(MPI_COMM_WORLD, &size); 
 double start_time = MPI_Wtime(); 
 double total_integral = 0.0; 
 if (rank == 0) { 

             // --- MAÎTRE --- 
      int current_task = 0; 
      double partial_integral; 
      MPI_Status status; 

              // Envoi initial des tâches aux travailleurs 
       for (int i = 1; i < size; i++) { 
             if (current_task >= N) break; 
                     MPI_Send(&current_task, 1, MPI_INT, i, 0, MPI_COMM_WORLD); 
                     current_task += TASK_SIZE; 
       } 

10 
