Directive  flush
#include <stdio.h>
#include <omp.h>
int main()
{
int rang, nb_taches, synch=0;
#pragma omp parallel private(rang,nb_taches)
{
rang=omp_get_thread_num();
nb_taches=omp_get_num_threads();
if (rang == 0) {
#pragma omp flush(synch)
while(synch != nb_taches-1);
}
else {
#pragma omp flush(synch)
while(synch != rang-1);
}
printf("Rang : %d ; synch : %d\n",rang,synch);
synch=rang;
#pragma omp flush(synch)
}
return 0;
} 152
