*   OpenMP Example - The THREADPRIVATE directive is used to make global 
*   file scope variables (C/C++)
******************************************************************************/
#include <omp.h>
#include <stdio.h>
#include <stdlib.h>

int  a, b,  tid;
float x;

#pragma omp threadprivate(a, x)

void main ()  {

/* Explicitly turn off dynamic threads */
  omp_set_dynamic(0);

  printf("1st Parallel Region:\n");
#pragma omp parallel private(b,tid)
  {
  tid = omp_get_thread_num();
  a = tid;
  b = tid;
  x = 1.1 * tid + 1.0;
  printf("Thread %d:   a,b,x= %d %d %f\n",tid,a,b,x);
  }  /* end of parallel section */

  tid = omp_get_thread_num();
  printf("************************************\n");
  printf("Master thread %d doing serial work here \n", tid);
  printf("************************************\n");

  printf("2nd Parallel Region:\n");
#pragma omp parallel private(tid)
  {
  tid = omp_get_thread_num();
  printf("Thread %d:   a,b,x= %d %d %f\n",tid,a,b,x);
  }  /* end of parallel section */

}

/******************************************************************************
* FILE: omp_workshare1.c
* DESCRIPTION:
*   OpenMP Example - Loop Work-sharing - C/C++ Version
*   In this example, the iterations of a loop are scheduled dynamically
*   across the team of threads.  A thread will perform CHUNK iterations
******************************************************************************/
#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#define CHUNKSIZE   5
#define N       60

void main (int argc, char *argv[]) 
{
int nthreads, tid, i, chunk;
float a[N], b[N], c[N];
double start, stop;

/* Some initializations */
for (i=0; i < N; i++)
  a[i] = b[i] = i * 1.0;

chunk = CHUNKSIZE;

omp_set_num_threads(4);

#pragma omp parallel shared(a,b,c,nthreads,chunk) private(i,tid)
  {
  tid = omp_get_thread_num();
  /* Only master thread does this */
  if (tid == 0)//#pragma omp master
    {
    nthreads = omp_get_num_threads();
    printf("Number of threads = %d TID=%d\n", nthreads,tid);
    }
  printf("Thread %d starting...\n",tid);
  start=omp_get_wtime();

  #pragma omp for schedule(static,chunk)
  for (i=0; i<N; i++)
    {
    c[i] = a[i] + b[i];
    printf("Thread %d: c[%d]= %f\n",tid,i,c[i]);
    }
	printf("Thread %d stopping...\n",tid);
  }  /* end of parallel section */
  stop = omp_get_wtime();
  printf("executing time = %lf   ", stop - start);
}

/******************************************************************************
* FILE: omp_workshare2.c
* DESCRIPTION:
*   OpenMP Example - Sections Work-sharing - C Version
*   In this example, the OpenMP SECTION directive is used to assign
*   different array operations to each thread that executes a SECTION. 
******************************************************************************/
#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#define N     5

int main (int argc, char *argv[]) 
{
int i, nthreads, tid;
float a[N], b[N], c[N], d[N];

/* Some initializations */
for (i=0; i<N; i++) {
  a[i] = i * 1.5;
  b[i] = i + 22.35;
  c[i] = d[i] = 0.0;
  }

#pragma omp parallel shared(a,b,c,d,nthreads) private(i,tid)
  {
  tid = omp_get_thread_num();
  /* Only master thread does this */
  if (tid == 3)
    {
    nthreads = omp_get_num_threads();
    printf("Number of threads = %d  tid=%d\n", nthreads,tid);
    }
  printf("Thread %d starting...\n",tid);

  #pragma omp sections
    {
     #pragma omp section
       {
         printf("Thread %d doing section 1\n",tid);
         for (i=0; i<N; i++)
         {
           c[i] = a[i] + b[i];
           printf("Thread %d: c[%d]= %f\n",tid,i,c[i]);
         }
      }

    #pragma omp section
      {
         printf("Thread %d doing section 2\n",tid);
        for (i=0; i<N; i++)
        {
          d[i] = a[i] * b[i];
          printf("Thread %d: d[%d]= %f\n",tid,i,d[i]);
        }
      }

    }  /* end of sections */

    printf("Thread %d done.\n",tid); 

  }  /* end of parallel section */

}

